              "react",
              "vue",
              "django",
              "fastapi",
              "rails",
              "spring-boot",
              "express",
              "angular",
              "svelte",
              "astro",
              "go-web",
              "rust-web",
              "dotnet",
              "nextjs",
              "flask",
              "nestjs",
              "kotlin-android",
              "node-cli",
              "node-library",
              "node-service"
